<script setup>
import {onMounted,reactive,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {getClubs} from '../../api/club'
import {getRounds,getSeasons} from '../../api/league'
import {createMatch,getMatches,getStadiums,updateMatch} from '../../api/match'
const router=useRouter(),rows=ref([]),total=ref(0),seasons=ref([]),rounds=ref([]),clubs=ref([]),stadiums=ref([]),loading=ref(false),visible=ref(false),editingId=ref(null),editingStatus=ref('DRAFT'),formRef=ref()
const query=reactive({page:1,size:10,seasonId:null,matchStatus:''})
const empty=()=>({seasonId:null,roundId:null,homeClubId:null,awayClubId:null,stadiumId:null,matchTime:''}),form=reactive(empty())
const rules={seasonId:[{required:true,message:'请选择赛季'}],roundId:[{required:true,message:'请选择轮次'}],homeClubId:[{required:true,message:'请选择主队'}],awayClubId:[{required:true,message:'请选择客队'}],stadiumId:[{required:true,message:'请选择场馆'}],matchTime:[{required:true,message:'请选择比赛时间'}]}
const load=async()=>{loading.value=true;try{const r=(await getMatches(query)).data;rows.value=r.records;total.value=r.total}finally{loading.value=false}}
watch(()=>form.seasonId,async id=>{rounds.value=id?(await getRounds(id)).data:[];if(!rounds.value.some(r=>r.roundId===form.roundId))form.roundId=null})
watch(()=>form.homeClubId,id=>{const c=clubs.value.find(v=>v.clubId===id);if(c?.homeStadiumId)form.stadiumId=c.homeStadiumId})
const open=async row=>{editingId.value=row?.matchId||null;editingStatus.value=row?.matchStatus||'DRAFT';Object.assign(form,empty(),row||{});if(form.seasonId)rounds.value=(await getRounds(form.seasonId)).data;visible.value=true}
const save=async()=>{await formRef.value.validate();if(form.homeClubId===form.awayClubId)return ElMessage.error('主队和客队不能相同');editingId.value?await updateMatch(editingId.value,form):await createMatch(form);visible.value=false;ElMessage.success('比赛已保存');await load()}
onMounted(async()=>{const [s,c,st]=await Promise.all([getSeasons(),getClubs({page:1,size:100}),getStadiums()]);seasons.value=s.data;clubs.value=c.data.records;stadiums.value=st.data.filter(v=>v.stadiumStatus==='ACTIVE');await load()})
</script>
<template><el-card><template #header><div class="head"><h2>比赛管理</h2><el-button type="primary" @click="open()">新建比赛</el-button></div></template><el-form inline><el-form-item label="赛季"><el-select v-model="query.seasonId" clearable style="width:180px"><el-option v-for="s in seasons" :key="s.seasonId" :label="s.seasonName" :value="s.seasonId"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.matchStatus" clearable style="width:160px"><el-option v-for="s in ['DRAFT','PUBLISHED','IN_PROGRESS','FINISHED','CANCELLED']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-button type="primary" @click="query.page=1;load()">查询</el-button></el-form><el-table v-loading="loading" :data="rows"><el-table-column prop="roundName" label="轮次"/><el-table-column label="对阵" min-width="220"><template #default="{row}">{{row.homeClubName}} vs {{row.awayClubName}}</template></el-table-column><el-table-column prop="matchTime" label="比赛时间" min-width="170"/><el-table-column prop="stadiumName" label="场馆"/><el-table-column prop="matchStatus" label="状态"/><el-table-column label="操作" width="170"><template #default="{row}"><el-button link type="primary" @click="router.push(`/admin/matches/${row.matchId}`)">维护</el-button><el-button v-if="['DRAFT','PUBLISHED'].includes(row.matchStatus)" link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><el-dialog v-model="visible" :title="editingId?'编辑比赛':'新建比赛'" width="620px"><el-alert v-if="editingStatus==='PUBLISHED'" title="已发布比赛仅允许修改比赛时间。" type="warning" :closable="false"/><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="赛季" prop="seasonId"><el-select v-model="form.seasonId" :disabled="editingStatus==='PUBLISHED'"><el-option v-for="s in seasons" :key="s.seasonId" :label="s.seasonName" :value="s.seasonId"/></el-select></el-form-item><el-form-item label="轮次" prop="roundId"><el-select v-model="form.roundId" :disabled="editingStatus==='PUBLISHED'"><el-option v-for="r in rounds" :key="r.roundId" :label="r.roundName" :value="r.roundId"/></el-select></el-form-item><el-form-item label="主队" prop="homeClubId"><el-select v-model="form.homeClubId" filterable :disabled="editingStatus==='PUBLISHED'"><el-option v-for="c in clubs" :key="c.clubId" :label="c.clubName" :value="c.clubId"/></el-select></el-form-item><el-form-item label="客队" prop="awayClubId"><el-select v-model="form.awayClubId" filterable :disabled="editingStatus==='PUBLISHED'"><el-option v-for="c in clubs" :key="c.clubId" :label="c.clubName" :value="c.clubId"/></el-select></el-form-item><el-form-item label="场馆" prop="stadiumId"><el-select v-model="form.stadiumId" :disabled="editingStatus==='PUBLISHED'"><el-option v-for="s in stadiums" :key="s.stadiumId" :label="s.stadiumName" :value="s.stadiumId"/></el-select></el-form-item><el-form-item label="比赛时间" prop="matchTime"><el-date-picker v-model="form.matchTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center}.head h2{margin:0}.el-pagination{justify-content:flex-end;margin-top:16px}.el-alert{margin-bottom:16px}</style>
